from pathlib import Path
import json, pandas as pd
ROOT=Path(__file__).resolve().parents[1]
records=pd.read_csv(ROOT/'01_Dataset/All_Subject_Records.csv').to_dict('records')
html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Attendance and Academic Performance</title><style>
:root{--purple:#7455d8;--blue:#3184e8;--ink:#202842;--muted:#68728b;--bg:#f4f6fc}*{box-sizing:border-box}body{margin:0;background:var(--bg);font:15px system-ui,Segoe UI,sans-serif;color:var(--ink)}header{padding:26px 4%;background:linear-gradient(115deg,#3b267e,#285cb1);color:white}h1{font-size:28px;margin:6px 0 10px;font-weight:700}header p{margin:5px 0;opacity:.9}header small{font-size:12px}nav{display:flex;gap:8px;padding:16px 4% 0;flex-wrap:wrap}button,select,input{font:inherit;border:1px solid #d8deec;border-radius:8px;background:white;padding:9px 12px;color:var(--ink)}button{cursor:pointer}button.active{background:var(--purple);color:white;border-color:var(--purple)}main{padding:18px 4% 40px}.filters{display:flex;gap:12px;align-items:end;flex-wrap:wrap;background:white;border:1px solid #e4e8f4;padding:16px;border-radius:12px}label{display:flex;flex-direction:column;gap:5px;font-size:12px;font-weight:600}label select{min-width:125px}.note{font-size:13px;color:var(--muted);line-height:1.6;margin:14px 0}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:18px 0}.kpi{padding:18px 20px;border-radius:12px;background:white;border-top:3px solid var(--purple)}.kpi strong{font-size:30px;display:block;margin-top:5px}.kpi span{font-size:12px;color:var(--muted)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.card{background:white;border:1px solid #e3e7f2;border-radius:12px;padding:18px;min-width:0}.card h2{font-size:18px;margin:0 0 10px}.card p{font-size:12px;color:var(--muted);line-height:1.5;margin:5px 0}.card svg{width:100%;height:auto;display:block}.wide{grid-column:1/-1}table{border-collapse:collapse;width:100%;font-size:13px}th,td{padding:10px;text-align:left;border-bottom:1px solid #edf0f7;white-space:nowrap}th{color:var(--purple);background:#f8f7fe;cursor:pointer}tr:hover td{background:#f7f5fd}.tablewrap{overflow:auto;max-height:510px}td button{padding:3px 7px;color:var(--purple);border:0}.badge{padding:3px 9px;border-radius:12px;background:#edf4ff;color:#2269c4}.fail{background:#f0eafa;color:#6741bc}.empty{text-align:center;padding:60px;color:var(--muted)}details{border-bottom:1px solid #e6e9f2;padding:10px}summary{cursor:pointer;font-weight:600}.modal{position:fixed;inset:0;background:#17213e88;display:flex;align-items:center;justify-content:center;padding:24px;z-index:3}.modal .card{max-width:700px;max-height:85vh;overflow:auto;width:100%}.hidden{display:none!important}footer{font-size:12px;padding:0 4% 30px;color:var(--muted)}a{color:#316dcc}svg text{font-family:system-ui,sans-serif;fill:#58637b;font-size:12px}svg .title{font-size:13px;fill:#202842}svg circle:hover{stroke:#202842;stroke-width:2;opacity:1}#scope{font-weight:600}@media(max-width:800px){.grid{grid-template-columns:1fr}.kpis{grid-template-columns:1fr 1fr}h1{font-size:23px}}@media print{nav,.filters,button{display:none}.card{break-inside:avoid}body{background:white}}
</style></head><body><header><small>SGSITS INDORE · REAL-LIFE DATA VISUALIZATION PROJECT</small><h1>Student Attendance and Academic Performance</h1><p>Parth Kalra &amp; Mahi Gupta</p><small>OFFLINE HTML ALTERNATIVE · UCI PUBLIC DATA · NOT SGSITS STUDENT RECORDS</small></header>
<nav id="nav"></nav><main><div class="filters">
<label>Subject<select id="subject"><option>Mathematics</option><option>Portuguese</option></select></label>
<label>School<select id="school"><option value="">All schools</option><option>GP</option><option>MS</option></select></label>
<label>Recorded sex<select id="sex"><option value="">All</option><option>F</option><option>M</option></select></label>
<label>Study time<select id="study"><option value="">All categories</option><option value="1">&lt;2 hours</option><option value="2">2-5 hours</option><option value="3">5-10 hours</option><option value="4">&gt;10 hours</option></select></label>
<label>Result<select id="result"><option value="">All results</option><option>Pass</option><option>Fail</option></select></label>
<button id="reset">Reset filters</button><button id="export">Export filtered CSV</button></div>
<p class="note"><span id="scope"></span> Absences are counts, not attendance percentages. Assignment completion and semester dates are unavailable. Pass uses the project rule G3 ≥ 10/20.</p>
<div class="kpis" id="kpis"></div><div id="content"></div></main><footer>Data: <a href="https://archive.ics.uci.edu/dataset/320/student+performance">UCI Student Performance</a>, Paulo Cortez, CC BY 4.0. Grades use a 0-20 scale. Subject cohorts overlap and must not be summed as unique students. Hover over marks for details. All data and charts work without an internet connection.</footer>
<div id="modal" class="modal hidden" role="dialog" aria-modal="true" aria-label="Course record details"></div><script>
const DATA=__DATA__;
const P='#7455d8',B='#3184e8',pages=['Student Performance Overview','Attendance and Academic Performance','Academic Performance Analysis','Student Data Explorer'];let page=0,sortKey='Record_ID',sortAsc=true,query='';
const $=id=>document.getElementById(id),fmt=(x,n=2)=>Number.isFinite(x)?x.toFixed(n):'N/A',mean=a=>a.length?a.reduce((s,v)=>s+v,0)/a.length:NaN;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function filtered(all=false){return DATA.filter(d=>(all||d.Subject===$('subject').value)&&(!$('school').value||d.school===$('school').value)&&(!$('sex').value||d.sex===$('sex').value)&&(!$('study').value||d.studytime==+$('study').value)&&(!$('result').value||d.Pass_Status===$('result').value))}
function corr(d,x,y){if(d.length<2)return NaN;let a=mean(d.map(r=>r[x])),b=mean(d.map(r=>r[y])),s=0,t=0,u=0;for(const r of d){s+=(r[x]-a)*(r[y]-b);t+=(r[x]-a)**2;u+=(r[y]-b)**2}return t*u?s/Math.sqrt(t*u):NaN}
function card(title,chart,note='',wide=false){return `<section class="card ${wide?'wide':''}"><h2>${title}</h2>${chart}<p>${note}</p></section>`}
function svg(inner,h=330){return `<svg viewBox="0 0 600 ${h}" role="img">${inner}</svg>`}
function bars(labels,vals,unit,counts=[],max=null){if(!vals.some(Number.isFinite))return '<div class="empty">No records for this selection</div>';let mx=max||(unit==='records'?Math.max(4,Math.ceil(Math.max(...vals.filter(Number.isFinite))*1.15/4)*4):Math.max(...vals.filter(Number.isFinite))*1.22)||1,inner='';for(let i=0;i<5;i++){let v=mx*i/4,y=265-v/mx*220;inner+=`<line x1="58" y1="${y}" x2="580" y2="${y}" stroke="#edf0f7"/><text x="48" y="${y+4}" text-anchor="end">${fmt(v,unit==='records'?0:1)}</text>`}let step=510/labels.length,w=Math.min(95,step*.65);labels.forEach((l,i)=>{let x=65+i*step+(step-w)/2,v=vals[i],hh=Number.isFinite(v)?v/mx*220:0;inner+=`<rect x="${x}" y="${265-hh}" width="${w}" height="${hh}" rx="3" fill="${i%2?B:P}"><title>${esc(l)}: ${fmt(v)} ${esc(unit)}${counts.length?'; n='+counts[i]:''}</title></rect><text x="${x+w/2}" y="${255-hh}" text-anchor="middle">${fmt(v,unit==='records'?0:2)}</text><text x="${x+w/2}" y="286" text-anchor="middle">${esc(l)}</text>${counts.length?`<text x="${x+w/2}" y="306" text-anchor="middle">n=${counts[i]}</text>`:''}`});inner+=`<text x="58" y="18" class="title">${esc(unit)}</text>`;return svg(inner)}
function scatter(d,x,y,xlabel,ylabel){if(!d.length)return '<div class="empty">No records for this selection</div>';let mx=Math.max(x==='absences'?1:20,...d.map(r=>r[x])),inner='';for(let i=0;i<=4;i++){let xx=60+i*125,yy=265-i*55;inner+=`<line x1="60" y1="${yy}" x2="560" y2="${yy}" stroke="#edf0f7"/><text x="50" y="${yy+4}" text-anchor="end">${i*5}</text><text x="${xx}" y="285" text-anchor="middle">${fmt(i*mx/4,0)}</text>`}for(const r of d)inner+=`<circle tabindex="0" cx="${60+r[x]/mx*500}" cy="${265-r[y]/20*220}" r="4.5" fill="${r.Pass_Status==='Pass'?B:P}" opacity=".42" onclick="record('${r.Record_ID}')"><title>${r.Record_ID}; ${xlabel}: ${r[x]}; ${ylabel}: ${r[y]}; ${r.Pass_Status}. Click for record.</title></circle>`;inner+=`<text x="60" y="18" class="title">${esc(ylabel)} (0-20)</text><text x="310" y="315" text-anchor="middle">${esc(xlabel)}</text>`;return svg(inner)}
function heat(d){const cols=['absences','studytime','failures','G1','G2','G3'];let inner='';cols.forEach((c,i)=>{inner+=`<text x="${157+i*65}" y="24" text-anchor="middle">${c}</text><text x="115" y="${65+i*40}" text-anchor="end">${c}</text>`;cols.forEach((v,j)=>{let r=corr(d,c,v),opacity=Number.isFinite(r)?.14+.86*Math.abs(r):.04;inner+=`<rect x="${125+j*65}" y="${40+i*40}" width="63" height="38" fill="${r<0?P:B}" opacity="${opacity}"/><text x="${157+j*65}" y="${65+i*40}" text-anchor="middle" style="fill:${Math.abs(r)>.65?'white':'#202842'}">${fmt(r,2)}</text>`})});return svg(inner,300)}
function group(d,key,labels){let groups=labels.map(l=>d.filter(r=>String(r[key])===String(l)));return {values:groups.map(g=>mean(g.map(r=>r.G3))),n:groups.map(g=>g.length)}}
function hist(d){let vals=Array.from({length:21},(_,i)=>d.filter(r=>r.G3===i).length),mx=Math.max(1,...vals),inner='';vals.forEach((v,i)=>{let x=53+i*25,h=v/mx*220;inner+=`<rect x="${x}" y="${265-h}" width="22" height="${h}" fill="${i<10?P:B}"><title>G3=${i}: ${v} records</title></rect>${i%2===0?`<text x="${x+10}" y="286" text-anchor="middle">${i}</text>`:''}`});for(let i=0;i<=4;i++)inner+=`<text x="45" y="${269-i*55}" text-anchor="end">${Math.round(mx*i/4)}</text>`;inner+='<text x="53" y="18" class="title">Student records</text><text x="310" y="315" text-anchor="middle">Final grade G3 (0-20), one-point bins</text>';return svg(inner)}
function render(){let d=filtered(),n=d.length,pass=d.filter(r=>r.G3>=10).length;$('scope').textContent=`${$('subject').value}: ${n} course records. `;$('nav').innerHTML=pages.map((p,i)=>`<button class="${i===page?'active':''}" onclick="page=${i};render()">${i+1}. ${p}</button>`).join('');$('kpis').innerHTML=[['Students in selected subject',n,'One record per student within subject'],['Average marks',fmt(mean(d.map(r=>r.G3)))+' / 20','Final grade G3'],['Pass percentage',fmt(n?pass/n*100:NaN,1)+'%','G3 ≥ 10, project threshold'],['Average absences',fmt(mean(d.map(r=>r.absences))),'Recorded count, not a percentage']].map(([l,v,s])=>`<div class="kpi">${l}<strong>${v}</strong><span>${s}</span></div>`).join('');
let out='',study=group(d,'studytime',[1,2,3,4]),ags=group(d,'Absence_Group',['0','1-5','6-10','11+']);
if(page===0){let cats=['Fail (0-9)','Satisfactory (10-11)','Good (12-13)','Very good (14-15)','Excellent (16-20)'];out=card('Pass vs fail',bars(['Pass','Fail'],[pass,n-pass],'records'),`Pass: ${pass}; fail: ${n-pass}.`)+card('Performance bands',bars(['0-9','10-11','12-13','14-15','16-20'],cats.map(c=>d.filter(r=>r.Performance_Category===c).length),'records'),'Project-defined bands; they are not SGSITS grading categories.')+card('Final grade distribution',hist(d),'All valid zero grades remain in the analysis.',true)}
if(page===1)out=card('Absences vs marks',scatter(d,'absences','G3','Recorded absences','Final grade G3'),`Pearson r = ${fmt(corr(d,'absences','G3'),3)}. Association does not establish causation.`)+card('Study time vs performance',bars(['<2 h','2-5 h','5-10 h','>10 h'],study.values,'Mean final grade (0-20)',study.n,20),'Study time is an ordinal category, not an exact duration.')+card('Correlation analysis',heat(d),'Pearson correlations use only the selected records. N/A means insufficient data or zero variance. Ordinal codes require cautious interpretation.')+card('Performance by absence groups',bars(['0','1-5','6-10','11+'],ags.values,'Mean final grade (0-20)',ags.n,20),'Exploratory groups. Zero absences can coexist with zero final grades.');
if(page===2){const all=filtered(true),subjects=['Mathematics','Portuguese'],g=group(all,'Subject',subjects);out=card('Grade distribution histogram',hist(d),'One integer grade per bin.')+card('Study-time category comparison',bars(['<2 h','2-5 h','5-10 h','>10 h'],study.values,'Mean final grade (0-20)',study.n,20),'Sample sizes are shown for each group.')+card('First period vs final grades',scatter(d,'G1','G3','First period grade G1','Final grade G3'),`Pearson r = ${fmt(corr(d,'G1','G3'),3)}.`)+card('Second period vs final grades',scatter(d,'G2','G3','Second period grade G2','Final grade G3'),`Pearson r = ${fmt(corr(d,'G2','G3'),3)}. G2 occurs before G3.`)+card('Subject cohort comparison',bars(subjects,g.values,'Mean final grade (0-20)',g.n,20),'This chart compares both subjects and ignores only the subject selector. Other filters apply. Cohorts overlap and differ in size. No causal subject ranking.',true)}
if(page===3){out=card('Student records',`<label>Search record ID or school<input id="search" placeholder="Example: MAT-0001" value="${esc(query)}" oninput="query=this.value;renderTable()"></label><p>Click a column header to sort. Click an ID to inspect its course record.</p><div id="records" class="tablewrap"></div>`,'Record IDs are generated row labels, not real student identifiers.',true)+card('Drill down by school and study time',drill(d),'Expand a school, then a study-time group to reach individual course records.',true)}
$('content').innerHTML='<div class="grid">'+out+'</div>';if(page===3)renderTable();window.dashboardState={page,n,pass,mean:mean(d.map(r=>r.G3)),r:corr(d,'absences','G3')};}
function renderTable(){let d=filtered().filter(r=>(r.Record_ID+' '+r.school).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>((a[sortKey]>b[sortKey])-(a[sortKey]<b[sortKey]))*(sortAsc?1:-1));let cols=['Record_ID','school','sex','age','absences','Study_Time_Category','G1','G2','G3','Pass_Status','Performance_Category'];$('records').innerHTML=`<p>${d.length} matching records</p><table><thead><tr>${cols.map(c=>`<th onclick="sortKey='${c}';sortAsc=!sortAsc;renderTable()">${c.replaceAll('_',' ')}</th>`).join('')}</tr></thead><tbody>${d.map(r=>'<tr>'+cols.map(c=>`<td>${c==='Record_ID'?`<button onclick="record('${r[c]}')">${r[c]}</button>`:c==='Pass_Status'?`<span class="badge ${r[c]==='Fail'?'fail':''}">${r[c]}</span>`:esc(r[c])}</td>`).join('')+'</tr>').join('')}</tbody></table>`}
function drill(d){return ['GP','MS'].map(s=>{let g=d.filter(r=>r.school===s);return `<details><summary>${s} · ${g.length} records · mean ${fmt(mean(g.map(r=>r.G3)))}</summary>${[1,2,3,4].map(t=>{let a=g.filter(r=>r.studytime===t);return `<details><summary>${['<2 h','2-5 h','5-10 h','>10 h'][t-1].replace('<','&lt;')} · n=${a.length}</summary>${a.map(r=>`<button onclick="record('${r.Record_ID}')">${r.Record_ID} · G3 ${r.G3}</button>`).join(' ')}</details>`}).join('')}</details>`}).join('')}
function record(id){let r=DATA.find(r=>r.Record_ID===id);$('modal').innerHTML=`<div class="card"><button onclick="$('modal').classList.add('hidden')" style="float:right">Close</button><h2>${id}</h2><p>Anonymous course record. No cross-subject identity linkage.</p><table>${Object.entries(r).map(([k,v])=>`<tr><th>${esc(k)}</th><td>${esc(v)}</td></tr>`).join('')}</table></div>`;$('modal').classList.remove('hidden')}
for(const id of ['subject','school','sex','study','result'])$(id).addEventListener('change',render);$('reset').onclick=()=>{['school','sex','study','result'].forEach(id=>$(id).value='');$('subject').value='Mathematics';query='';render()};$('export').onclick=()=>{let d=filtered(),cols=Object.keys(DATA[0]),csv=[cols.join(','),...d.map(r=>cols.map(c=>'"'+String(r[c]).replaceAll('"','""')+'"').join(','))].join('\r\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='Filtered_Student_Records.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};document.addEventListener('keydown',e=>{if(e.key==='Escape')$('modal').classList.add('hidden')});render();
</script></body></html>'''
(ROOT/'07_Dashboard_Alternative/Interactive_Dashboard.html').write_text(html.replace('__DATA__',json.dumps(records,separators=(',',':'))),encoding='utf-8')
print('Standalone offline HTML dashboard created')
